CREATE TABLE IF NOT EXISTS leaders (slug text PRIMARY KEY, name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS actions (id bigserial PRIMARY KEY, leader_slug text NOT NULL REFERENCES leaders(slug), action_date date NOT NULL, city text NOT NULL, neighborhood text, activity_type text NOT NULL, conversations integer NOT NULL CHECK(conversations>=0), support integer NOT NULL CHECK(support>=0), undecided integer NOT NULL CHECK(undecided>=0), materials integer NOT NULL DEFAULT 0 CHECK(materials>=0), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attachments (id bigserial PRIMARY KEY, action_id bigint NOT NULL REFERENCES actions(id) ON DELETE CASCADE, filename text NOT NULL, original_name text NOT NULL, mime_type text NOT NULL, size_bytes integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS actions_leader_date_idx ON actions(leader_slug,action_date DESC);
